        (-1.5707963267948966, -1.5707963267948963, -1.5707963267948963, -1.5707963267948966, -1.5707963267948966, 0.0),
        (0.03499999999999999, 0.015000000000000032, 0.015000000000000006, 0.013000000000000067, 0.012999999999999966, 4.8138576458356397e-17),
        (2.0816681711721685e-17, -0.31270000000000014, 2.168404344971009e-17, -0.2500000000000002, 1.0408340855860843e-17, -0.03100000000000004),
        1, False,
        (2, 3),
        (0, 5),
